def main() -> int:
    args = parser().parse_args()
    try:
        args.func(args)
    except (SupervisionLogError, OSError, json.JSONDecodeError) as exc:
        print(json.dumps({"error": str(exc)}, sort_keys=True))
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
